<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class AnnouncementController extends Controller {
 public function index(Request $r){$p=$r->attributes->get('academic_period');$u=$r->user();$q=DB::table('announcements as a')->leftJoin('study_groups as g','g.id','=','a.study_group_id')->leftJoin('users as u','u.id','=','a.author_id')->when($p,fn($x)=>$x->where(fn($z)=>$z->whereNull('a.academic_period_id')->orWhere('a.academic_period_id',$p->id)))->where(fn($x)=>$x->whereNull('a.starts_at')->orWhere('a.starts_at','<=',now()))->where(fn($x)=>$x->whereNull('a.ends_at')->orWhere('a.ends_at','>=',now()));$gid=$u->student_id?DB::table('students')->where('id',$u->student_id)->value('current_group_id'):null;if($u->hasRole('student')||$u->hasRole('starosta'))$q->where(fn($x)=>$x->where('a.audience','all')->orWhere(fn($y)=>$y->where('a.audience','group')->where('a.study_group_id',$gid)));return view('announcements.index',['items'=>$q->select('a.*','g.name as group_name','u.name as author_name')->orderByDesc('a.is_important')->orderByDesc('a.created_at')->get()]);}
 public function store(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('head_academic'),403);$d=$r->validate(['title'=>'required|string|max:180','body'=>'required|string|max:5000','audience'=>'required|in:all,group','study_group_id'=>'nullable|exists:study_groups,id','ends_at'=>'nullable|date','is_important'=>'nullable|boolean']);$p=$r->attributes->get('academic_period');DB::table('announcements')->insert(['academic_period_id'=>$p?->id,'author_id'=>$r->user()->id,'title'=>$d['title'],'body'=>$d['body'],'audience'=>$d['audience'],'study_group_id'=>$d['audience']==='group'?($d['study_group_id']??null):null,'starts_at'=>now(),'ends_at'=>$d['ends_at']??null,'is_important'=>(bool)($d['is_important']??false),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Объявление опубликовано.');}
}
